gi,go=G['Demo pair 1 input'],G['Demo pair 1 output']; gt=G['Test input']
def f(g):
    H_,W_=len(g),len(g[0])
    cols={x for r in g for x in r}
    bg=max(cols,key=lambda c:sum(r.count(c)for r in g))
    out=[r[:] for r in g]
    # flood from border over bg cells; bg cells not reached are holes
    reach=set();q=collections.deque()
    for i in range(H_):
        for j in (0,W_-1):
            if g[i][j]==bg and (i,j) not in reach:reach.add((i,j));q.append((i,j))
    for j in range(W_):
        for i in (0,H_-1):
            if g[i][j]==bg and (i,j) not in reach:reach.add((i,j));q.append((i,j))
    while q:
        a,b=q.popleft()
        for da,db in((1,0),(-1,0),(0,1),(0,-1)):
            na,nb=a+da,b+db
            if 0<=na<H_ and 0<=nb<W_ and g[na][nb]==bg and (na,nb) not in reach:
                reach.add((na,nb));q.append((na,nb))
    holes={(i,j) for i in range(H_) for j in range(W_) if g[i][j]==bg and (i,j) not in reach}
    seen=set()
    for c in cols-{bg}:
        for s in comps(g,c):
            ys=[p[0] for p in s];xs=[p[1] for p in s]
            r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
            full=all(g[i][j]==c or (i,j) in holes for i in range(r0,r1+1) for j in range(c0,c1+1))
            if full and any((i,j) in holes for i in range(r0,r1+1) for j in range(c0,c1+1)):
                for p in s: out[p[0]][p[1]]=3
    return out
